pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 5 ether);
        vm.prank(user);
        c.deposit{value: 2}();
        vm.prank(user);
        c.withdrawAll();
        vm.prank(user);
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}
